// Do not edit: edit the Python and regenerate (`./build.sh spwm-tables`).
//
// These are S-PWM driver-chip register tables. The gateware is one engine
// and the chip is data; this is that data, in the form the firmware writes
// over the chip_table CSR at boot.
//
// NOTHING HERE HAS BEEN TESTED ON HARDWARE.

/// One register row: the same address on three separate driver chips,
/// which do not have to carry the same value.
#[derive(Clone, Copy)]
pub struct Row {
    pub r: u16,
    pub g: u16,
    pub b: u16,
}

/// A chip's protocol data: the rotating registers, the wrapper slots,
/// and the three grammar bits that differ between parts.
pub struct Chip {
    pub name: &'static str,
    pub regs: &'static [Row],
    pub wrappers: &'static [Row],
    pub slots: u8,
    pub rot_slot: u8,
    pub mid_latch: bool,
    /// ROW/OE pulse width in panel clocks, and the width used for
    /// the first row of a frame. Equal on parts that do not care.
    pub row_pulse: u8,
    pub row_pulse_first: u8,
    pub data_latch: u8,
    pub row_address: u8,
    pub row_addr_shift: u8,
    pub row_serial: u8,
    pub chan_rev: u8,
    /// Column permutation inside each driver (XOR on the channel
    /// index) and the fetch-address advance in sweeps. Both live in
    /// the gateware's `latch_cfg` CSR, NOT in the register table, so
    /// the firmware has to apply them explicitly at boot -- the
    /// bitstream's reset values come from whatever chip the PRESET
    /// named, which for the HUB320 panel is not this one.
    pub chan_xor: u8,
    pub sweep_adv: u8,
    /// Display passes per data frame MINUS ONE -- the chip's own
    /// reg0x03. Sets BOTH the W12 cadence (11.6.2) and the
    /// displayable grey range (11.7.5), so it must match the
    /// register table or every mixed colour clips.
    pub passes_m1: u8,
    /// Register address carrying the scan row count, and its mask.
    pub scan_reg: u8,
    pub scan_mask: u8,
    /// Register address carrying output current, if this chip has one.
    pub bright_reg: u8,
    pub bright_max: u8,
    /// Scan rate the capture was taken at. A table used at a different
    /// scan rate is an extrapolation -- registers other than the scan
    /// count do change with it.
    pub capture_scan: u16,
}

pub const MAX_REGS: usize = 64;
pub const MAX_WRAPPERS: usize = 8;

